    public static void DrawPage(TFMPage _page, TFMHtmlViewerCtrl _htmlViewer)
    {
        TFMPageTypeAttribute pageType;
        TFMDrawPage drawPage;

        pageType = new SysDictClass(classIdGet(_page)).getAttribute(classStr(TFMPageTypeAttribute));

        if (!pageType)
        {
            return;
        }
        drawPage = SysExtensionAppClassFactory::getClassFromSysAttribute(classStr(TFMDrawPage), pageType);
		if (!drawPage)
        {
            _htmlViewer.parmHtml('<html><body><h3>' + "@TFM:Previewnotavailable" + '</h3></body></html>');
            return;
        }
        drawPage.DrawPage(_page,_htmlViewer);
    }
